class BowlingGame:
    def __init__(self):
        self._rolls = []
        self._frame = 0
        self._pins_standing = 10
        self._rolls_in_frame = 0
        self._ten_frame_rolls = 0
        self._game_over = False

    def roll(self, pins):
        if pins < 0 or pins > 10:
            raise Exception("pins must be between 0 and 10")
        if self._game_over:
            raise Exception("cannot roll after the game is over")
        if pins > self._pins_standing:
            raise Exception("two rolls in a frame cannot score more than 10 points")

        self._rolls.append(pins)
        self._pins_standing -= pins

        if self._frame < 9:
            self._rolls_in_frame += 1
            if self._pins_standing == 0 or self._rolls_in_frame == 2:
                self._frame += 1
                self._pins_standing = 10
                self._rolls_in_frame = 0
        else:
            self._ten_frame_rolls += 1
            # A strike or a completed spare clears the rack for a fill ball.
            cleared = pins == 10 or self._pins_standing == 0
            if cleared:
                self._pins_standing = 10
            first_was_strike = self._rolls[-2] == 10
            if self._ten_frame_rolls >= 3 or (
                self._ten_frame_rolls == 2 and not first_was_strike and not cleared
            ):
                self._game_over = True

    def score(self):
        if not self._game_over:
            raise Exception("cannot score an incomplete game")

        total = 0
        i = 0
        for frame in range(9):
            if self._rolls[i] == 10:
                total += 10 + self._rolls[i + 1] + self._rolls[i + 2]
                i += 1
            else:
                total += self._rolls[i] + self._rolls[i + 1]
                if self._rolls[i] + self._rolls[i + 1] == 10:
                    total += self._rolls[i + 2]
                i += 2
        total += sum(self._rolls[i:])
        return total

